class HitCounter {
    private final AtomicInteger hits = new AtomicInteger();
    void hit() { hits.incrementAndGet(); }
    int hits() { return hits.get(); }
}

@Test
@Timeout(10)
void countsHitsFromManyThreads() throws Exception {
    int threads = 8, perThread = 10_000;
    HitCounter counter = new HitCounter();
    CyclicBarrier start = new CyclicBarrier(threads);
    try (var executor = Executors.newFixedThreadPool(threads)) {
        List<Future<?>> futures = new ArrayList<>();
        for (int t = 0; t < threads; t++) {
            futures.add(executor.submit(() -> {
                start.await();                      // cùng xuất phát
                for (int i = 0; i < perThread; i++) counter.hit();
                return null;
            }));
        }
        for (Future<?> f : futures) f.get();      // lỗi trong thread phụ bay ra đây
    }
    assertEquals(threads * perThread, counter.hits());
}
